/** Icons that don't ship all three sizes, keyed by `"<category>/<name>"`. */
const SIZE_OVERRIDES: Readonly<Record<string, readonly IconSizeType[]>> = {
  "animals-nature/Rat5Icon": ["lg"],
  "animals-nature/Rat4Icon": ["lg"],
  "animals-nature/Sheep2Icon": ["lg"],
  "animals-nature/Rat3Icon": ["lg"],
  "business-finance/UserCoin2Icon": ["lg"],
  "business-finance/CryptoExchangeIcon": ["lg"],
  "sport/Bicycle3Icon": ["md", "lg"],
  "sport/OlympicGamesIcon": ["lg"],
  "transportation/Bicycle3Icon": ["sm"],
  "ui-layout/HammerScrewdriverIcon": ["md", "lg"],
  "ui-layout/WrenchesIcon": ["md", "lg"],
  "users/People2Icon": ["lg"],
};

export const ICONS: readonly IconEntryType[] = ICON_PAIRS.map(([name, category]) => {
  const words = nameWords(name);
  const categoryWords = category.toLowerCase().split(/[-\s]+/);
  const tags = Array.from(new Set([...words.map((word) => word.toLowerCase()), ...categoryWords]));
  return {
    name,
    category,
    categoryLabel: categoryLabel(category),
    label: iconLabel(name),
    tags,
    sizes: SIZE_OVERRIDES[`${category}/${name}`] ?? ALL_SIZES,
  };
});

export const ICON_CATEGORIES: readonly string[] = Array.from(new Set(ICONS.map((icon) => icon.category))).sort((a, b) =>
  categoryLabel(a).localeCompare(categoryLabel(b)),
);
